#include <optional>
#include <variant>
#include <string>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::optional<std::string> text{std::in_place, 3, 'x'};
    std::variant<int, std::string> value{std::in_place_type<std::string>, "hello"};
    value.emplace<0>(7);
    assert(*text == "xxx" && std::get<0>(value) == 7);
}
